FuncDef.Code:
float opSmoothInfRepeatX(inout vec3 p, float spacing, float smoothness)
{
    float halfsize = spacing*0.5;
    float cellIndex = floor((p.x + halfsize)/spacing);

    //p.x = mod(p.x + halfsize, spacing) - halfsize;
    p.x = modEx(p.x + halfsize, spacing, smoothness) - halfsize;

    return cellIndex;
}
